//! 🧊️ Admitted native BRep topology, analytic geometry, p-curves and all spline arrays.
use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint2,SemioPoint3};
use crate::standards::v1::subsets::brep::schema::snapshot::{SemioBrepSnapshot,BrepVertex,BrepEdge,BrepLoop,BrepLoopEdge,BrepFace,BrepShell,BrepShellFace,BrepSolid,BrepSolidShell,BrepCoedge,BrepCurve,BrepCurve2,BrepSurface,STDIO_SEMIOBREP_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(crate) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioBrepSnapshot,ValueError>{native::decode(payload,STDIO_SEMIOBREP_DOCUMENT_SCHEMA,control,binary,document)}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))}
fn point2(reader:&mut store::ByteReader<'_>)->Result<SemioPoint2,ValueError>{Ok(SemioPoint2{x:f64(reader)?,y:f64(reader)?})}
fn point3(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,ValueError>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn boolean(reader:&mut store::ByteReader<'_>)->Result<bool,ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(false),1=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid BRep native boolean"))}}
fn u32(reader:&mut store::ByteReader<'_>)->Result<u32,ValueError>{u32::try_from(reader.read_varint_u64().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"BRep native integer exceeds unsigned32"))}
fn numbers_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<f64>,ValueError>{native::binary_list(reader,control,limits,entities,|reader,_,_|f64(reader))}
